stock=stock_at_target
future_lost=0
first_stockout=-1
for ev in sorted(obj['future_schedule'], key=lambda x:(x['event_time'], x['event_id'])):
    if ev['kind']=='receipt':
        stock += ev['quantity']
    else:
        unmet=max(0, ev['quantity']-stock)
        if unmet>0 and first_stockout==-1:
            first_stockout=ev['event_time']
        future_lost += unmet
        stock -= min(stock, ev['quantity'])
